// Extract listicleId and auth token from the failed execution data
const execData = $input.first().json;

// Navigate n8n execution data structure to find webhook input
let listicleId = 0;
let authHeader = '';
let errorMessage = 'Unknown n8n error';
let lastNode = 'Unknown node';

try {
  // Get webhook node data from the execution
  const runData = execData.runData || execData.data?.resultData?.runData || {};
  const webhookKey = Object.keys(runData).find(k => k.toLowerCase().includes('webhook'));

  if (webhookKey && runData[webhookKey]?.[0]?.data?.main?.[0]?.[0]?.json) {
    const webhookInput = runData[webhookKey][0].data.main[0][0].json;

    // Extract listicleId from body
    if (webhookInput.body?.listicleId) {
      listicleId = webhookInput.body.listicleId;
    }

    // Extract original Authorization header
    if (webhookInput.headers?.authorization) {
      authHeader = webhookInput.headers.authorization;
    }
  }

  // Get error info from the execution
  const execError = execData.error || execData.data?.resultData?.error || {};
  errorMessage = execError.message || execError.description || errorMessage;

  // Try to get lastNodeExecuted from the error data
  if (execData.lastNodeExecuted) {
    lastNode = execData.lastNodeExecuted;
  }
} catch (e) {
  // Fallback: use what we can from the Error Trigger
  const triggerData = $('Error Trigger').first().json;
  if (triggerData.execution?.error?.message) {
    errorMessage = triggerData.execution.error.message;
  }
  if (triggerData.execution?.lastNodeExecuted) {
    lastNode = triggerData.execution.lastNodeExecuted;
  }
}

// Derive error endpoint URL from the callback URL pattern
let errorUrl = '';
try {
  const webhookKey = Object.keys(execData.runData || execData.data?.resultData?.runData || {}).find(k => k.toLowerCase().includes('webhook'));
  if (webhookKey && execData.runData?.[webhookKey]?.[0]?.data?.main?.[0]?.[0]?.json?.body?.callbackUrl) {
    errorUrl = execData.runData[webhookKey][0].data.main[0][0].json.body.callbackUrl.replace('/callback', '/error');
  } else if (execData.data?.resultData?.runData?.[webhookKey]?.[0]?.data?.main?.[0]?.[0]?.json?.body?.callbackUrl) {
    errorUrl = execData.data.resultData.runData[webhookKey][0].data.main[0][0].json.body.callbackUrl.replace('/callback', '/error');
  }
} catch (e) {
  // Ignore, errorUrl stays empty
}

return [{
  json: {
    listicleId: listicleId,
    errorMessage: errorMessage.slice(0, 2000),
    lastNodeExecuted: lastNode,
    errorUrl: errorUrl,
    authHeader: authHeader
  }
}];
